namespace bptree {

class Node {
public:
    bool isLeaf;
    std::vector<int> keys;
    Node* ptr2next;
    union ptr {
        std::vector<Node*> ptr2Tree;
        std::vector<FILE*> dataPtr;
        ptr() {}
        ~ptr() {}
    } ptr2TreeOrData;

    Node() {
        this->isLeaf = false;
        this->ptr2next = NULL;
